"""Render the SQL of all migrations (offline mode) into ``docs/schema.sql``.

Usage: ``python tools/gen_schema.py [--check]`` from ``backend/``. ``--check`` exits 1 if the
committed file is out of date (used by the test suite).
"""

from __future__ import annotations

import io
import sys
from pathlib import Path

from alembic import command
from alembic.config import Config

BACKEND = Path(__file__).resolve().parents[1]
TARGET = BACKEND.parent / "docs" / "schema.sql"
HEADER = (
    "-- CarboRewind control-plane schema (PostgreSQL 16).\n"
    "-- GENERATED by `python backend/tools/gen_schema.py` from the Alembic migrations.\n"
    "-- Do not edit by hand.\n\n"
)


def render() -> str:
    buffer = io.StringIO()
    cfg = Config(str(BACKEND / "alembic.ini"), output_buffer=buffer)
    cfg.attributes["url"] = "postgresql+psycopg://offline@localhost/offline"
    command.upgrade(cfg, "head", sql=True)
    lines = [line.rstrip() for line in buffer.getvalue().splitlines()]
    return HEADER + "\n".join(lines).strip() + "\n"


def main(argv: list[str]) -> int:
    sql = render()
    if "--check" in argv:
        if not TARGET.is_file() or TARGET.read_text() != sql:
            print(f"{TARGET} is out of date: run python tools/gen_schema.py", file=sys.stderr)
            return 1
        return 0
    TARGET.write_text(sql)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
